void topic_type_support<::CorpusFlatDataBinding::Sample >::register_type(
    dds::domain::DomainParticipant& participant,
    const std::string& name)
{
    ::rti::domain::register_type_plugin(participant, name, &::CorpusFlatDataBinding::wireloom_Sample_flatdata_create_plugin, &::CorpusFlatDataBinding::wireloom_Sample_flatdata_delete_plugin);
}

std::vector<char>& topic_type_support<::CorpusFlatDataBinding::Sample>::to_cdr_buffer(
    std::vector<char>& buffer,
    const ::CorpusFlatDataBinding::Sample& sample,
    dds::core::policy::DataRepresentationId representation)
{
    if (representation != dds::core::policy::DataRepresentation::auto_id()
        && representation != dds::core::policy::DataRepresentation::xcdr2())
        throw dds::core::InvalidArgumentError("FlatData CDR supports XCDR2 only.");
    const auto* bytes = sample.get_buffer();
    const auto encapsulation = (static_cast<unsigned int>(bytes[0]) << 8)
        | static_cast<unsigned int>(bytes[1]);
    if (encapsulation != RTI_XCDR_ENCAPSULATION_ID_CDR2_BE
        && encapsulation != RTI_XCDR_ENCAPSULATION_ID_CDR2_LE)
        throw dds::core::InvalidArgumentError("FlatData sample does not contain an XCDR2 CDR buffer.");
    buffer.assign(reinterpret_cast<const char*>(bytes),
        reinterpret_cast<const char*>(bytes) + sample.buffer_size());
    return buffer;
}

void topic_type_support<::CorpusFlatDataBinding::Sample >::from_cdr_buffer(
    ::CorpusFlatDataBinding::Sample& sample,
    const std::vector<char>& buffer)
{
    if (buffer.size() != RTI_XCDR_ENCAPSULATION_SIZE + ::CorpusFlatDataBinding::SampleOffset::serialized_size(0))
        throw dds::core::InvalidArgumentError("FlatData XCDR2 buffer has an unexpected size.");
    const auto encapsulation = (static_cast<unsigned int>(static_cast<unsigned char>(buffer[0])) << 8)
        | static_cast<unsigned int>(static_cast<unsigned char>(buffer[1]));
    if (encapsulation != RTI_XCDR_ENCAPSULATION_ID_CDR2_BE
        && encapsulation != RTI_XCDR_ENCAPSULATION_ID_CDR2_LE)
        throw dds::core::InvalidArgumentError("FlatData buffer is not XCDR2 CDR.");
    std::copy(buffer.begin(), buffer.end(), reinterpret_cast<char*>(sample.get_buffer()));
}

void topic_type_support<::CorpusFlatDataBinding::Sample >::reset_sample(::CorpusFlatDataBinding::Sample&)
{
    throw dds::core::InvalidArgumentError(
        "FlatData sample lifecycle is managed by the RTI FlatData API.");
}

void topic_type_support<::CorpusFlatDataBinding::Sample >::allocate_sample(::CorpusFlatDataBinding::Sample&, int, int)
{
    throw dds::core::InvalidArgumentError(
        "FlatData sample lifecycle is managed by the RTI FlatData API.");
}

void topic_type_support<::CorpusFlatDataBinding::SamplePlainHelper>::register_type(
    dds::domain::DomainParticipant& participant,
    const std::string& name)
{
    ::rti::domain::register_type_plugin(
        participant,
        name,
        &::WireloomRti612TypePlugin<::CorpusFlatDataBinding::SamplePlainHelper>::create,
        &::WireloomRti612TypePlugin<::CorpusFlatDataBinding::SamplePlainHelper>::destroy);
}

std::vector<char>& topic_type_support<::CorpusFlatDataBinding::SamplePlainHelper>::to_cdr_buffer(
    std::vector<char>& buffer,
    const ::CorpusFlatDataBinding::SamplePlainHelper& sample,
    dds::core::policy::DataRepresentationId representation)
{
    if (representation != dds::core::policy::DataRepresentation::auto_id()
        && representation != dds::core::policy::DataRepresentation::xcdr2())
        throw dds::core::InvalidArgumentError("FlatData helper CDR supports XCDR2 only.");
    buffer.resize(12);
    buffer[0] = static_cast<char>(RTI_XCDR_ENCAPSULATION_ID_CDR2_BE >> 8);
    buffer[1] = static_cast<char>(RTI_XCDR_ENCAPSULATION_ID_CDR2_BE & 0xff);
    buffer[2] = 0;
    buffer[3] = 0;
    const auto value_0 = static_cast<std::uint32_t>(sample.id);
    buffer[4] = static_cast<char>((value_0 >> 24) & 0xff);
    buffer[5] = static_cast<char>((value_0 >> 16) & 0xff);
    buffer[6] = static_cast<char>((value_0 >> 8) & 0xff);
    buffer[7] = static_cast<char>(value_0 & 0xff);
    const auto value_1 = static_cast<std::uint32_t>(sample.value);
    buffer[8] = static_cast<char>((value_1 >> 24) & 0xff);
    buffer[9] = static_cast<char>((value_1 >> 16) & 0xff);
    buffer[10] = static_cast<char>((value_1 >> 8) & 0xff);
    buffer[11] = static_cast<char>(value_1 & 0xff);
    return buffer;
}

void topic_type_support<::CorpusFlatDataBinding::SamplePlainHelper>::from_cdr_buffer(
    ::CorpusFlatDataBinding::SamplePlainHelper& sample,
    const std::vector<char>& buffer)
{
    if (buffer.size() != 12)
        throw dds::core::InvalidArgumentError("FlatData helper CDR has an unexpected size.");
    const auto encapsulation = (static_cast<unsigned int>(static_cast<unsigned char>(buffer[0])) << 8)
        | static_cast<unsigned int>(static_cast<unsigned char>(buffer[1]));
    if (encapsulation != RTI_XCDR_ENCAPSULATION_ID_CDR2_BE
        && encapsulation != RTI_XCDR_ENCAPSULATION_ID_CDR2_LE)
        throw dds::core::InvalidArgumentError("FlatData helper buffer is not XCDR2 CDR.");
    const bool little_endian = encapsulation == RTI_XCDR_ENCAPSULATION_ID_CDR2_LE;
    std::uint32_t value_0;
    if (little_endian) value_0 = static_cast<std::uint32_t>(static_cast<unsigned char>(buffer[4])) | (static_cast<std::uint32_t>(static_cast<unsigned char>(buffer[5])) << 8) | (static_cast<std::uint32_t>(static_cast<unsigned char>(buffer[6])) << 16) | (static_cast<std::uint32_t>(static_cast<unsigned char>(buffer[7])) << 24);
    else value_0 = (static_cast<std::uint32_t>(static_cast<unsigned char>(buffer[4])) << 24) | (static_cast<std::uint32_t>(static_cast<unsigned char>(buffer[5])) << 16) | (static_cast<std::uint32_t>(static_cast<unsigned char>(buffer[6])) << 8) | static_cast<std::uint32_t>(static_cast<unsigned char>(buffer[7]));
    std::memcpy(&sample.id, &value_0, sizeof(value_0));
    std::uint32_t value_1;
    if (little_endian) value_1 = static_cast<std::uint32_t>(static_cast<unsigned char>(buffer[8])) | (static_cast<std::uint32_t>(static_cast<unsigned char>(buffer[9])) << 8) | (static_cast<std::uint32_t>(static_cast<unsigned char>(buffer[10])) << 16) | (static_cast<std::uint32_t>(static_cast<unsigned char>(buffer[11])) << 24);
    else value_1 = (static_cast<std::uint32_t>(static_cast<unsigned char>(buffer[8])) << 24) | (static_cast<std::uint32_t>(static_cast<unsigned char>(buffer[9])) << 16) | (static_cast<std::uint32_t>(static_cast<unsigned char>(buffer[10])) << 8) | static_cast<std::uint32_t>(static_cast<unsigned char>(buffer[11]));
    std::memcpy(&sample.value, &value_1, sizeof(value_1));
}

void topic_type_support<::CorpusFlatDataBinding::SamplePlainHelper>::reset_sample(::CorpusFlatDataBinding::SamplePlainHelper& sample)
{
    sample = ::CorpusFlatDataBinding::SamplePlainHelper{};
}

void topic_type_support<::CorpusFlatDataBinding::SamplePlainHelper>::allocate_sample(::CorpusFlatDataBinding::SamplePlainHelper& sample, int, int)
{
    sample = ::CorpusFlatDataBinding::SamplePlainHelper{};
}
